"""Pinned ClickHouse server processes, private directories and loopback sockets only."""
import json,os,pathlib,shutil,socket,subprocess,tempfile,time,urllib.request,urllib.error
from xml.sax.saxutils import escape
from continuation_clickhouse_fixture import CONFIG

def free_port():
 with socket.socket() as s:s.bind(('127.0.0.1',0));return s.getsockname()[1]

class Server:
 def __init__(self,tcp_port=None,cluster_ports=(),remote_user='default',remote_password=''):self.tcp_port=tcp_port or free_port();self.http_port=free_port();self.cluster_ports=tuple(cluster_ports);self.remote_user=remote_user;self.remote_password=remote_password;self.process=None;self.log=None;self.temp=None
