  version=subprocess.run([executable,'server','--version'],capture_output=True,text=True,timeout=3)
  if version.returncode or '25.8.1.5101' not in version.stdout:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: ClickHouse25.8.1.5101 required')
  self.temp=tempfile.TemporaryDirectory(prefix='of-ch-server-');self.root=pathlib.Path(self.temp.name)
  for folder in ['data','tmp','user_files','format_schemas','access']:(self.root/folder).mkdir()
  users=self.root/'users.xml';users.write_text('<clickhouse><profiles><default><max_threads>2</max_threads><max_memory_usage>67108864</max_memory_usage><log_queries>0</log_queries></default></profiles><users><default><password></password><networks><ip>127.0.0.1</ip></networks><profile>default</profile><quota>default</quota><access_management>1</access_management></default></users><quotas><default></default></quotas></clickhouse>')
  shards=''.join('<shard><replica><host>127.0.0.1</host><port>'+str(port)+'</port><user>'+escape(self.remote_user)+'</user><password>'+escape(self.remote_password)+'</password></replica></shard>' for port in self.cluster_ports)
  remote='<remote_servers><exercise_cluster>'+shards+'</exercise_cluster></remote_servers>' if shards else ''
  extra=f'''<listen_host>127.0.0.1</listen_host><tcp_port>{self.tcp_port}</tcp_port><http_port>{self.http_port}</http_port>
<path>{escape(str(self.root/'data'))}/</path><tmp_path>{escape(str(self.root/'tmp'))}/</tmp_path>
<user_files_path>{escape(str(self.root/'user_files'))}/</user_files_path><format_schema_path>{escape(str(self.root/'format_schemas'))}/</format_schema_path>
<access_control_path>{escape(str(self.root/'access'))}/</access_control_path><users_config>{escape(str(users))}</users_config>
<max_server_memory_usage>268435456</max_server_memory_usage><mark_cache_size>1048576</mark_cache_size><uncompressed_cache_size>1048576</uncompressed_cache_size>
<max_concurrent_queries>8</max_concurrent_queries><max_connections>32</max_connections><max_io_thread_pool_size>4</max_io_thread_pool_size>
<background_move_pool_size>1</background_move_pool_size><background_fetches_pool_size>1</background_fetches_pool_size><background_common_pool_size>1</background_common_pool_size><async_insert_threads>1</async_insert_threads>
{remote}'''
  config=self.root/'config.xml';config.write_text(CONFIG.replace('<level>error</level>','<level>information</level>').replace('</clickhouse>',extra+'</clickhouse>'))
  self.log=(self.root/'server.log').open('wb')
  try:
   self.process=subprocess.Popen([executable,'server','--config-file='+str(config)],cwd=self.root,stdout=self.log,stderr=self.log,env={**os.environ,'HOME':str(self.root),'TMPDIR':str(self.root)})
   deadline=time.monotonic()+25;last_probe=None
   while time.monotonic()<deadline:
    if self.process.poll() is not None:raise AssertionError('native server startup failed: '+(self.root/'server.log').read_text(errors='replace')[-3500:])
    try:
     last_probe=self.query('SELECT 1 AS ready')
     if len(last_probe)==1 and str(last_probe[0].get('ready'))=='1':break
    except (OSError,urllib.error.URLError) as error:last_probe=repr(error)
    time.sleep(.04)
   else:raise AssertionError('native server readiness deadline: '+repr(last_probe)+' '+(self.root/'server.log').read_text(errors='replace')[-3500:])
   print('NATIVE_CLICKHOUSE_SERVER_READY:'+str(self.tcp_port),flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def execute(self,sql,*,user=None,password=None):
  req=urllib.request.Request('http://127.0.0.1:'+str(self.http_port)+'/',data=sql.encode(),method='POST')
  if user is not None:req.add_header('X-ClickHouse-User',user)
  if password is not None:req.add_header('X-ClickHouse-Key',password)
  opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
  try:
   with opener.open(req,timeout=6) as response:return response.read().decode()
  except urllib.error.HTTPError as response:
   detail=response.read().decode(errors='replace');response.close();raise AssertionError('native ClickHouse SQL failed: '+detail[-2400:])
 def query(self,sql):return [json.loads(line) for line in self.execute(sql+' FORMAT JSONEachRow').splitlines() if line]
 def __exit__(self,*args):
  if self.process is not None:
   if self.process.poll() is None:self.process.terminate()
   try:self.process.wait(4)
   except subprocess.TimeoutExpired:self.process.kill();self.process.wait(2)
  if self.log:self.log.close()
  if self.temp:self.temp.cleanup()

